// package.json — @better-auth/mcp is NOT part of better-auth core in 1.7.5
//   "@better-auth/mcp": "1.7.5"   (pulls @better-auth/oauth-provider@1.7.5)

import { betterAuth } from "better-auth";
import { jwt } from "better-auth/plugins";
import { mcp } from "@better-auth/mcp";
import { Hono } from "hono";

export const auth = betterAuth({
  baseURL: process.env.BASE_URL,          // basePath defaults to "/api/auth"
  secret: process.env.BETTER_AUTH_SECRET,
  database: /* your adapter */ undefined as any,
  plugins: [
    jwt(),                                 // mcp() reads the issuer from here; omit -> baseURL
    mcp({
      loginPage: "/login",
      consentPage: "/consent",
      resource: `${process.env.BASE_URL}/mcp`,  // https, or http on localhost/loopback; no ? and no #
      // allowDynamicClientRegistration defaults to FALSE — do not set it
    }),
  ],
});

const app = new Hono();
const h = (c: any) => auth.handler(c.req.raw);
app.all("/api/auth/*", h);
app.all("/.well-known/*", h);   // THE ONLY routing MCPRouter must add. No custom PRM handler.
// app.all("/mcp", yourMcpHandler)  <- your own MCP endpoint

// DCR-is-off test (both halves pass today, both fail if someone flips the flag):
const as = await (await fetch(`${BASE}/api/auth/.well-known/oauth-authorization-server`)).json();
assert(!("registration_endpoint" in as));
const reg = await fetch(`${BASE}/api/auth/oauth2/register`, { method: "POST", body: "{}" });
assert(reg.status === 403);
assert((await reg.json()).error_description === "Client registration is disabled");
